#[test]
fn test_integers_and_reals_become_fx() {
    crate::testport::assert_eq(fxt_raw(fx_of_int(3)), 196608, "3 is 3*65536");
    crate::testport::assert_eq(fxt_raw(fx_of_int(-2)), -131072, "-2");
    crate::testport::assert_eq(fxt_raw(fx_of_real(5, 1)), 32768, "0.5 is 32768");
    crate::testport::assert_eq(fxt_raw(fx_of_real(25, 2)), 16384, "0.25");
    crate::testport::assert_eq(fxt_raw(fx_of_real(-75, 2)), -49152, "-0.75");
    crate::testport::assert_eq(fxt_raw(fx_of_real(1, 5)), 1, "0.00001 rounds to 1 unit (0.655)");
    crate::testport::assert_eq(fxt_raw(fx_of_real(1, 6)), 0, "0.000001 is under half a unit");
    crate::testport::assert_eq(fxt_raw(fx_of_real(1234567, 3)), 80908583, "1234.567 is 80908583 units");
    crate::testport::assert_eq(fx_round(fx_of_real(149, 2)), 1, "1.49 rounds to 1");
    crate::testport::assert_eq(fx_round(fx_of_real(150, 2)), 2, "1.50 rounds up");
    crate::testport::assert_eq(fx_round(fx_of_real(-150, 2)), -1, "-1.50 rounds up, toward positive");
    crate::testport::assert_eq(fx_round(fx_of_real(-151, 2)), -2, "-1.51");
    crate::testport::assert_eq(fx_floor(fx_of_real(-1, 1)), -1, "floor of -0.1 is -1");
    crate::testport::assert_eq(fx_floor(fx_of_real(19, 1)), 1, "floor of 1.9");
}
#[test]
fn test_multiplication_and_division_round_half_away_from_zero() {
    crate::testport::assert_eq(fxt_raw(fx_mul(fx_of_int(3), fx_of_int(4))), 786432, "3*4");
    crate::testport::assert_eq(fxt_raw(fx_mul(fx_of_real(5, 1), fx_of_real(5, 1))), 16384, "0.5*0.5");
    crate::testport::assert_eq(fxt_raw(fx_mul(fx_of_int(-3), fx_of_real(5, 1))), -98304, "-3*0.5");
    crate::testport::assert_eq(fxt_raw(fx_mul(1 as i64, 32768 as i64)), 1, "half a unit rounds away: 1");
    crate::testport::assert_eq(fxt_raw(fx_mul(-1 as i64, 32768 as i64)), -1, "and -1");
    crate::testport::assert_eq(fxt_raw(fx_mul(1 as i64, 32767 as i64)), 0, "under half: 0");
    crate::testport::assert_eq(fxt_raw(fx_div(fx_of_int(1), fx_of_int(4))), 16384, "1/4");
    crate::testport::assert_eq(fxt_raw(fx_div(fx_of_int(10), fx_of_int(-4))), -163840, "10/-4");
    crate::testport::assert_eq(fxt_raw(fx_div(fx_of_int(1), 0 as i64)), 0, "division by zero is 0, not a fault");
    crate::testport::assert_eq(fxt_raw(fx_muldiv(27783 as i64, fx_of_int(12), 100000 as i64)), 218494, "a glyph width: 277.83/1000 em at 12 is 3.334");
    crate::testport::assert_eq(fxt_raw(fx_muldiv(-7 as i64, 1 as i64, 2 as i64)), -4, "-3.5 rounds away");
    crate::testport::assert_eq(fxt_raw(fx_muldiv(7 as i64, 1 as i64, -2 as i64)), -4, "3.5 over -1 ... away");
    crate::testport::assert_eq(fxt_raw(fx_muldiv(-7 as i64, 1 as i64, -2 as i64)), 4, "positive again");
}
#[test]
fn test_hostile_magnitudes_wrap_and_clamp_but_never_fault() {
    crate::testport::assert_eq(fx_round(fx_clamp(fx_of_int(2147483647))), 268435456, "a huge integer is clamped to 2^28");
    crate::testport::assert_that(fx_clamp(9000000000000000 as i64) == (17592186044416 as i64), "clamped above");
    crate::testport::assert_that(fx_clamp(-9000000000000000 as i64) == (-17592186044416 as i64), "clamped below");
    crate::testport::assert_eq(fx_round(fx_of_int(2147483647)), 2147483647, "the largest integer");
    crate::testport::assert_eq(fx_round(fx_of_int(2147483647)), 2147483647, "saturation in the round");
}
#[test]
fn test_square_roots_and_lengths() {
    crate::testport::assert_eq(fx_isqrt(0 as i64) as i32, 0, "isqrt 0");
    crate::testport::assert_eq(fx_isqrt(1 as i64) as i32, 1, "isqrt 1");
    crate::testport::assert_eq(fx_isqrt(15 as i64) as i32, 3, "isqrt 15");
    crate::testport::assert_eq(fx_isqrt(16 as i64) as i32, 4, "isqrt 16");
    crate::testport::assert_eq(fx_isqrt(2147395600 as i64) as i32, 46340, "isqrt of 46340^2");
    crate::testport::assert_eq(fxt_raw(fx_sqrt(fx_of_int(4))), 131072, "sqrt 4 = 2");
    crate::testport::assert_eq(fxt_raw(fx_sqrt(fx_of_int(2))), 92681, "sqrt 2 = 1.41421 (floor of 92681.9)");
    crate::testport::assert_eq(fxt_raw(fx_sqrt(-5 as i64)), 0, "sqrt of a negative is 0");
    crate::testport::assert_eq(fx_round(fx_hypot(fx_of_int(3), fx_of_int(4))), 5, "3-4-5");
    crate::testport::assert_eq(fx_round(fx_hypot(fx_of_int(-3), fx_of_int(4))), 5, "signs do not matter");
    crate::testport::assert_eq(fx_round(fx_hypot(fx_of_int(0), fx_of_int(0))), 0, "the zero vector");
    crate::testport::assert_eq(fx_round(fx_hypot(fx_of_int(1000000), fx_of_int(1000000))), 1414214, "large vectors keep nine digits");
}
#[test]
fn test_atan2_is_exact_on_the_axes_and_close_between() {
    crate::testport::assert_eq(fx_atan2(0 as i64, fx_of_int(1)), 0, "east");
    crate::testport::assert_eq(fx_atan2(fx_of_int(1), 0 as i64), 9000, "north");
    crate::testport::assert_eq(fx_atan2(0 as i64, fx_of_int(-1)), 18000, "west");
    crate::testport::assert_eq(fx_atan2(fx_of_int(-1), 0 as i64), 27000, "south");
    crate::testport::assert_eq(fx_atan2(0 as i64, 0 as i64), 0, "the zero vector");
    crate::testport::assert_eq(fx_atan2(fx_of_int(1), fx_of_int(1)), 4500, "45");
    crate::testport::assert_eq(fx_atan2(fx_of_int(1), fx_of_int(-1)), 13500, "135");
    crate::testport::assert_eq(fx_atan2(fx_of_int(-1), fx_of_int(-1)), 22500, "225");
    crate::testport::assert_eq(fx_atan2(fx_of_int(-1), fx_of_int(1)), 31500, "315");
    crate::testport::assert_eq(fx_atan2(fx_of_int(1), fx_of_int(2)), 2656, "atan(0.5) = 26.565 degrees (CORDIC: within a centi-degree)");
    crate::testport::assert_eq(fx_atan2(fx_of_int(3), fx_of_int(4)), 3687, "atan(3/4) = 36.87 degrees");
    crate::testport::assert_eq(fx_atan2(fx_of_int(1), fx_of_int(100)), 57, "atan(0.01) = 0.573 degrees");
    crate::testport::assert_eq(fx_atan2(1 as i64, fx_of_int(100)), 0, "a hair above east is still 0");
    crate::testport::assert_eq(fx_atan2(fx_of_int(-1), fx_of_int(100)), 35943, "a hair below east wraps to 359.43");
    crate::testport::assert_eq(fx_atan2(1099511627776 as i64, 1099511627776 as i64), 4500, "huge vectors are normalised");
    crate::testport::assert_eq(fx_atan2(3 as i64, 4 as i64), 3687, "tiny vectors are normalised");
}
#[test]
fn test_an_fx_is_two_cells() {
    let c: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let big: i64 = 98765432109 as i64;
    let neg: i64 = -98765432109 as i64;
    crate::testport::assert_eq(fx_push(c, big), 0, "first at 0");
    crate::testport::assert_eq(fx_push(c, neg), 2, "second at 2");
    crate::testport::assert_eq(crate::port::cells_len(c), 4, "four cells");
    crate::testport::assert_that(fx_get(c, 0) == big, "a positive value above 2^32 survives");
    crate::testport::assert_that(fx_get(c, 2) == neg, "and a negative one");
    fx_put(c, 0, -1 as i64);
    crate::testport::assert_that(fx_get(c, 0) == (-1 as i64), "minus one (all ones in the low half)");
    fx_put(c, 0, 2147483648 as i64);
    crate::testport::assert_that(fx_get(c, 0) == (2147483648 as i64), "2^31: the low half's sign bit is not a sign");
    crate::testport::assert_that(fx_join(0, -1) == (4294967295 as i64), "join reads the low half unsigned");
}
#[test]
fn test_matrices_compose_in_pdf_order() {
    let c: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut i: i32 = 0;
    while i < 48 {
        fx_push(c, 0 as i64);
        i += 2;
    }
    // 0: translate (10, 20); 12: scale 2 by 3; 24: result
    mx_translate(c, 0, fx_of_int(10), fx_of_int(20));
    mx_set(c, 12, fx_of_int(2), 0 as i64, 0 as i64, fx_of_int(3), 0 as i64, 0 as i64);
    // translate then scale: (1,1) -> (11,21) -> (22,63)
    mx_mul(c, 24, 0, 12);
    crate::testport::assert_eq(fx_round(mx_x(c, 24, fx_of_int(1), fx_of_int(1))), 22, "x");
    crate::testport::assert_eq(fx_round(mx_y(c, 24, fx_of_int(1), fx_of_int(1))), 63, "y");
    // scale then translate: (1,1) -> (2,3) -> (12,23)
    mx_mul(c, 24, 12, 0);
    crate::testport::assert_eq(fx_round(mx_x(c, 24, fx_of_int(1), fx_of_int(1))), 12, "x, other order");
    crate::testport::assert_eq(fx_round(mx_y(c, 24, fx_of_int(1), fx_of_int(1))), 23, "y, other order");
    // a product written over an operand
    mx_mul(c, 12, 12, 0);
    crate::testport::assert_eq(fx_round(mx_x(c, 12, fx_of_int(1), fx_of_int(1))), 12, "dst is x");
    mx_ident(c, 36);
    mx_mul(c, 36, 36, 36);
    crate::testport::assert_eq(fx_round(mx_x(c, 36, fx_of_int(7), fx_of_int(9))), 7, "the identity squared");
    crate::testport::assert_eq(fx_round(mx_y(c, 36, fx_of_int(7), fx_of_int(9))), 9, "is the identity");
}
#[test]
fn test_a_rotation_by_90_turns_the_axes() {
    let c: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut i: i32 = 0;
    while i < 24 {
        fx_push(c, 0 as i64);
        i += 2;
    }
    // [0 1 -1 0 0 0]: x axis to y, y axis to -x
    mx_set(c, 0, 0 as i64, fx_of_int(1), fx_of_int(-1), 0 as i64, 0 as i64, 0 as i64);
    crate::testport::assert_eq(fx_round(mx_x(c, 0, fx_of_int(1), 0 as i64)), 0, "(1,0) x");
    crate::testport::assert_eq(fx_round(mx_y(c, 0, fx_of_int(1), 0 as i64)), 1, "(1,0) y");
    crate::testport::assert_eq(fx_round(mx_x(c, 0, 0 as i64, fx_of_int(1))), -1, "(0,1) x");
    mx_copy(c, 12, 0);
    mx_mul(c, 12, 12, 0);
    crate::testport::assert_eq(fx_round(mx_x(c, 12, fx_of_int(1), 0 as i64)), -1, "twice is 180 degrees");
}
pub(crate) fn fxt_dist(v: i64, want: i32) -> i32 {
    // |v - want| in raw Fx units.
    let d: i32 = (v as i32) - want;
    if d < 0 {
        return 0 - d;
    }
    return d;
}
#[test]
fn test_sine_and_cosine_are_exact_at_the_axes_and_close_between() {
    crate::testport::assert_eq(fxt_raw(fx_cos(0)), 65536, "cos 0");
    crate::testport::assert_eq(fxt_raw(fx_sin(0)), 0, "sin 0");
    crate::testport::assert_eq(fxt_raw(fx_cos(9000)), 0, "cos 90");
    crate::testport::assert_eq(fxt_raw(fx_sin(9000)), 65536, "sin 90");
    crate::testport::assert_eq(fxt_raw(fx_cos(18000)), -65536, "cos 180");
    crate::testport::assert_eq(fxt_raw(fx_sin(18000)), 0, "sin 180");
    crate::testport::assert_eq(fxt_raw(fx_cos(27000)), 0, "cos 270");
    crate::testport::assert_eq(fxt_raw(fx_sin(27000)), -65536, "sin 270");
    crate::testport::assert_that(fxt_dist(fx_sin(4500), 46341) <= 2, "sin 45 = 0.70711");
    crate::testport::assert_that(fxt_dist(fx_cos(4500), 46341) <= 2, "cos 45");
    crate::testport::assert_that(fxt_dist(fx_sin(3000), 32768) <= 2, "sin 30 = 0.5");
    crate::testport::assert_that(fxt_dist(fx_cos(6000), 32768) <= 2, "cos 60 = 0.5");
    crate::testport::assert_that(fxt_dist(fx_cos(13500), -46341) <= 2, "cos 135");
    crate::testport::assert_that(fxt_dist(fx_sin(31500), -46341) <= 2, "sin 315");
    crate::testport::assert_that(fxt_dist(fx_sin(-4500), -46341) <= 2, "a negative angle");
    crate::testport::assert_that(fxt_dist(fx_cos(40500), 46341) <= 2, "an angle past a turn");
}
